struct GlowTipScrubberFilm { var tip: Double; var held: Double; var down: Double; var lit: Double; var reveal: Double; var shown: Double; var marks: Double }
enum GlowTipScrubberMotion {
    static let points = 160, hour = 3600000.0, day = 24 * hour, nowPrice = 84283.52, now = 1738314000000.0
    static let loop = 9.0, pressAt = 0.6, bloom = 0.2, sweepTo = 4.0, backTo = 5.2, jumpTo = 6.0, lift = 0.25, fadeAt = 6.35, fadeFor = 0.25, drawAt = 6.6, drawFor = 1.4, marksIn = 0.3, startX = 0.015, turnX = 0.93, dipX = 0.545, userHold = 3.0, overshoot = 1.2
    static func clamp(_ t: Double) -> Double { min(1, max(0, t)) }
    static func ease(_ t: Double) -> Double { let u = clamp(t); return u < 0.5 ? 4 * pow(u, 3) : 1 - pow(-2 * u + 2, 3) / 2 }
    static func back(_ t: Double) -> Double { let u = clamp(t); return 1 + (overshoot + 1) * pow(u - 1, 3) + overshoot * pow(u - 1, 2) }
    static func filmAt(_ t: Double, _ still: Bool) -> GlowTipScrubberFilm {
        let down = t >= pressAt && t < jumpTo ? 1.0 : 0.0
        if still { return .init(tip: dipX, held: down, down: down, lit: down, reveal: 1, shown: 1, marks: down != 0 ? 0 : 1) }
        var tip = startX
        if t >= pressAt { tip = startX + (turnX - startX) * ease((t - pressAt) / (sweepTo - pressAt)) }
        if t >= sweepTo { tip = turnX + (dipX - turnX) * ease((t - sweepTo) / (backTo - sweepTo)) }
        if t >= backTo { tip = min(1, dipX + (1 - dipX) * back((t - backTo) / (jumpTo - backTo))) }
        let held = t < jumpTo ? clamp((t - pressAt) / bloom) : 1 - clamp((t - jumpTo) / lift)
        var lit = held, reveal = 1.0, shown = 1 - clamp((t - fadeAt) / fadeFor)
        if t >= drawAt { reveal = clamp((t - drawAt) / drawFor); tip = reveal; shown = 1; lit = clamp((t - drawAt) / bloom) * (1 - clamp((t - drawAt - drawFor) / lift)) }
        let marks = (1 - clamp((t - pressAt) / bloom)) + clamp((t - drawAt - drawFor) / marksIn)
        return .init(tip: tip, held: held, down: down, lit: lit, reveal: reveal, shown: shown, marks: clamp(marks))
    }
    static func priceAt(_ prices: [Double], _ x: Double) -> Double { let at = clamp(x) * Double(prices.count - 1), i = min(prices.count - 2, Int(floor(at))); return prices[i] + (prices[i + 1] - prices[i]) * (at - Double(i)) }
    // toFixed rounds the exact binary value; multiplying a Double first can change a half-cent tie.
    static func fixed(_ value: Double) -> String {
        let bits = abs(value).bitPattern, exponent = Int((bits >> 52) & 0x7ff) - 1023 - 52
        let scaled = ((bits & 0x000fffffffffffff) | (UInt64(1) << 52)) * 100
        let cents: UInt64
        if exponent >= 0 { cents = scaled << exponent }
        else { let shift = -exponent; cents = shift >= 64 ? 0 : (scaled >> shift) + ((scaled & ((UInt64(1) << shift) - 1)) >= (UInt64(1) << (shift - 1)) ? 1 : 0) }
        return "\(cents / 100).\(String(format: "%02d", Int(cents % 100)))"
    }
    static func grouped(_ value: Double) -> String {
        let parts = fixed(value).split(separator: "."), whole = String(parts[0])
        return whole.enumerated().map { i, char in (i > 0 && (whole.count - i) % 3 == 0 ? "," : "") + String(char) }.joined() + "." + parts[1]
    }
    static func dateLabel(_ ms: Double, _ hours: Bool) -> String {
        let quarter = 900000.0, date = Date(timeIntervalSince1970: floor(ms / quarter + 0.5) * quarter / 1000)
        var calendar = Calendar(identifier: .gregorian); calendar.timeZone = TimeZone(secondsFromGMT: 0)!
        let c = calendar.dateComponents([.month, .day, .year, .hour, .minute], from: date), names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], day = "\(names[c.month! - 1]) \(c.day!)"
        if !hours { return "\(day), \(c.year!)" }
        return "\(day), \(c.hour! % 12 == 0 ? 12 : c.hour! % 12):\(String(format: "%02d", c.minute!)) \(c.hour! < 12 ? "AM" : "PM")"
    }
}
